#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, M;
    cin >> n >> M;

    vector<vector<int>> divisors_list(n + 1);
    for (int divisor = 2; divisor <= n; ++divisor) {
        for (int multiple = 2 * divisor; multiple <= n; multiple += divisor) {
            divisors_list[multiple].push_back(divisor);
        }
    }

    vector<long long> F(n + 1, 0);
    F[1] = 1;
    if (n >= 2) F[2] = 2;

    for (int i = 3; i <= n; ++i) {
        F[i] = (2 * F[i - 1] + F[i / (i - 1)]) % M;
        long long sum_diff = 0;
        for (int d : divisors_list[i]) {
            if (d >= 2 && d <= i - 2) {
                sum_diff += F[i / d] - F[(i - 1) / d];
            }
        }
        F[i] = (F[i] + sum_diff) % M;
    }

    cout << F[n] % M << "\n";

    return 0;
}
